                ];

                // 鬼魂类型数据
                const ghostsData = [
                    { id: 'spirit', name: '魂魄', evidence: ['emf', 'spiritBox', 'book'] },
                    { id: 'phantom', name: '魅影', evidence: ['emf', 'spiritBox', 'dots'] },
                    { id: 'poltergeist', name: '骚灵', evidence: ['spiritBox', 'fingerprints', 'book'] },
                    { id: 'banshee', name: '女妖', evidence: ['fingerprints', 'orb', 'dots'] },
