                    { id: 'oni', name: '赤鬼', evidence: ['emf', 'freezing', 'dots'] },
                    { id: 'yokai', name: '妖怪', evidence: ['spiritBox', 'orb', 'dots'] },
                    { id: 'hantu', name: '寒魔', evidence: ['fingerprints', 'orb', 'freezing'] },
                    { id: 'goryo', name: '御灵', evidence: ['emf', 'fingerprints', 'dots'] },
                    { id: 'myling', name: '鬼婴', evidence: ['emf', 'fingerprints', 'book'] },
                    { id: 'wraith', name: '怨灵', evidence: ['spiritBox', 'orb', 'freezing'] },
                    { id: 'twins', name: '孪魂', evidence: ['emf', 'spiritBox', 'freezing'] },
                    { id: 'raiju', name: '雷魂', evidence: ['emf', 'orb', 'dots'] },
                    { id: 'obake', name: '幻妖', evidence: ['emf', 'fingerprints', 'orb'] },
                    { id: 'mimic', name: '拟魂', evidence: ['spiritBox', 'fingerprints', 'freezing', 'orb'] },
                    { id: 'moroi', name: '魔洛伊', evidence: ['spiritBox', 'book', 'freezing'] },
                    { id: 'deogen', name: '刹耶', evidence: ['orb', 'book', 'dots'] },
                    { id: 'thaye', name: '雾影', evidence: ['spiritBox', 'book', 'dots'] }
                ];

                // 被选中的证据集合
                const selectedEvidences = ref([]);
                // 用户选择的鬼魂ID
                const selectedGhostId = ref(null);

                // 切换证据选择状态
                const toggleEvidence = (evidenceId) => {
                    const index = selectedEvidences.value.indexOf(evidenceId);
                    if (index === -1) {
                        selectedEvidences.value.push(evidenceId);
                    } else {
                        selectedEvidences.value.splice(index, 1);
                    }
                };

                // 选择鬼魂
                const selectGhost = (ghostId) => {
                    // 如果已经选中，再次点击则取消选择
                    if (selectedGhostId.value === ghostId) {
                        selectedGhostId.value = null;
                    } else {
                        selectedGhostId.value = ghostId;
                    }
                };

                // 计算匹配的鬼魂
                const matchedGhosts = computed(() => {
                    if (selectedEvidences.value.length === 0) return [];

                    return ghostsData.filter(ghost => {
                        return selectedEvidences.value.every(evidence => 
                            ghost.evidence.includes(evidence)
                        );
                    });
                });

                // 重置鬼魂选择
                watch(selectedEvidences, () => {
                    selectedGhostId.value = null;
                });

                // 是否可以确认鬼魂
                const canConfirm = computed(() => {
                    return matchedGhosts.value.length === 1 || 
                           (matchedGhosts.value.length > 1 && selectedGhostId.value);
                });

                // 确认鬼魂并发送消息
                const confirmGhost = () => {
                    let ghostName = "";

                    // 如果只有一个匹配鬼魂
                    if (matchedGhosts.value.length === 1) {
                        ghostName = matchedGhosts.value[0].name;
                    } 
                    // 如果有多个匹配鬼魂且用户已选择
                    else if (selectedGhostId.value) {
                        const selectedGhost = ghostsData.find(g => g.id === selectedGhostId.value);
                        if (selectedGhost) {
                            ghostName = selectedGhost.name;
                        }
                    }

                    if (ghostName) {
                        // 构建发送命令
                        const command = `/send 已经确认鬼魂为${ghostName}返回车中 |/trigger`;

                        // 调用发送方法
                        try {
                            triggerSlash(command);
                            console.log("命令已发送:", command);
                        } catch (e) {
                            console.error("发送命令失败:", e);
                            alert(`发送命令失败: ${e.message}`);
                        }
                    } else {
                        alert("请选择或确认要返回的鬼魂！");
                    }
                };

                return {
                    evidenceData,
                    selectedEvidences,
                    matchedGhosts,
                    selectedGhostId,
                    toggleEvidence,
                    selectGhost,
                    canConfirm,
                    confirmGhost
                };
            }
        }).mount('#app');
    </script>
